conn = get_conn()
total = 0
for numero, enunciado in QUESTOES.items():
    rows = conn.execute("""
        SELECT id FROM questoes
        WHERE escola='ITA' AND ano=2025 AND fase='1'
        AND disciplina='ingles' AND numero=?
    """, (numero,)).fetchall()
    for row in rows:
        conn.execute("UPDATE questoes SET enunciado=? WHERE id=?", (enunciado, row['id']))
        total += 1
        print(f"Q{numero}: atualizado")

conn.commit()
conn.close()
